import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

/**
 * The box an example renders in. Inline it is capped to the reading width; with `fill` (a
 * full-screen slide) it takes the whole panel, so an example sized from its container (`w-full`,
 * `h-full` with a minimum) grows with it, while one with a natural size stays centred.
 */
export const ShowcaseSurface = ({
  children,
  fill = false,
}: {
  children?: ReactNode;
  fill?: boolean;
}) => (
  <div
    data-slot="component-preview"
    className={cn(
      "relative isolate mx-auto flex w-full min-w-0 items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center",
      fill ? "flex-1" : "min-h-64 max-w-3xl",
    )}
  >
    {children}
  </div>
);

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";
import OverviewExample from "./variants/overview";

import ReadOnlyExample from "./variants/read-only";

import StatusExample from "./variants/status";

import ProgressExample from "./variants/progress";

import AutoplayExample from "./variants/autoplay";

import VerticalExample from "./variants/vertical";

import TabsExample from "./variants/tabs";


const COMPONENT = "step-indicator";

const meta = {
  parameters: {
    docs: { description: { component: componentDocumentation(COMPONENT) } },
    layout: "centered",
  },
} satisfies Meta;

export default { ...meta, title: "Blocks/Step Indicator",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj<typeof meta>;

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: variantDocumentation(COMPONENT, "overview") },
      source: { code: "import { useState } from "react";
import { StepIndicator } from "@/registry/erbium/blocks/step-indicator";

const tips = [
  "Drag files onto any page to upload them.",
  "Press Command K to search every project.",
  "Pin a project to keep it at the top.",
  "Share a link to invite anyone to a file.",
];

export default function StepIndicatorExample() {
  const [tip, setTip] = useState(0);

  return (
    <div className="flex w-72 flex-col items-center gap-4">
      <p className="min-h-12 text-center text-control text-pretty">{tips[tip]}</p>
      <StepIndicator count={tips.length} value={tip} onValueChange={setTip} aria-label="Tips" />
    </div>
  );
}
" },
    },
  },
  render: OverviewExample,
};

export const ReadOnly: Story = {
  parameters: {
