export default function StepIndicatorReadOnlyExample() {
  return <StepIndicator count={5} value={2} aria-label="Question 3 of 5" />;
}
" },
    },
  },
  render: ReadOnlyExample,
};

export const Status: Story = {
  parameters: {
    docs: {
      description: { story: variantDocumentation(COMPONENT, "status") },
      source: { code: "import { useState } from "react";
import { StepIndicator, StepIndicatorItem } from "@/registry/erbium/blocks/step-indicator";

const photos = [
  { disabled: false, invalid: false, label: "Beach" },
