export const Progress: Story = {
  parameters: {
    docs: {
      description: { story: variantDocumentation(COMPONENT, "progress") },
      source: { code: "import { useState } from "react";
import { StepIndicator } from "@/registry/erbium/blocks/step-indicator";
import { Slider } from "@/registry/erbium/ui/slider";

export default function StepIndicatorProgressExample() {
  const [progress, setProgress] = useState(0.4);

  return (
    <div className="flex w-64 flex-col items-center gap-4">
      <StepIndicator count={4} value={1} progress={progress} aria-label="Upload progress" />
      <Slider
        aria-label="Progress"
        min={0}
        max={100}
        value={progress * 100}
        onValueChange={(next) => {
          setProgress(next / 100);
        }}
      />
    </div>
  );
}
" },
    },
  },
  render: ProgressExample,
};

export const Autoplay: Story = {
  parameters: {
    docs: {
      description: { story: variantDocumentation(COMPONENT, "autoplay") },
      source: { code: "import { useState } from "react";
import { StepIndicator } from "@/registry/erbium/blocks/step-indicator";
import { Button } from "@/registry/erbium/ui/button";
import { Card, CardContent } from "@/registry/erbium/ui/card";
import { Icon } from "@/registry/erbium/ui/icon";
import { StatefulIcon } from "@/registry/erbium/ui/stateful-icon";

const folders = ["Inbox", "Drafts", "Sent", "Archive"];

export default function StepIndicatorAutoplayExample() {
  const [index, setIndex] = useState(0);
  const [paused, setPaused] = useState(false);

  return (
    <div className="flex flex-col items-center gap-4">
      <Card className="size-40">
        <CardContent className="flex min-h-0 flex-1 items-center justify-center">
          <span className="text-title font-semibold">{folders[index]}</span>
        </CardContent>
      </Card>
      <div className="flex items-center gap-3">
        <Button
          variant="outline"
          size="icon-sm"
          className="rounded-full"
          onClick={() => {
            setPaused(!paused);
          }}
        >
          <StatefulIcon
            state={paused ? "play" : "pause"}
            icons={{ pause: <Icon name="pause" />, play: <Icon name="play" /> }}
          />
          <span className="sr-only">{paused ? "Play folders" : "Pause folders"}</span>
        </Button>
        <StepIndicator
          variant="dots"
          count={folders.length}
          value={index}
          onValueChange={setIndex}
          autoplay={{ duration: 3000, paused }}
          aria-label="Folders"
        />
      </div>
    </div>
  );
}
" },
    },
  },
  render: AutoplayExample,
};

export const Vertical: Story = {
  parameters: {
